// Helper function: checks whether `sub` matches the slice of `main` starting at index `start`.
// Requires that start + sub.len() <= main.len().
fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Iterate over all indices of sub and compare elements.
    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

// Main function: checks whether `sub` appears as a contiguous subarray in `main`.
fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    let n = main.len();
    let m = sub.len();

    // The empty subarray always qualifies.
    if m == 0 {
        return true;
    }

    // If sub is longer than main, it cannot be a contiguous subarray.
    if m > n {
        return false;
    }

    // Iterate through possible start indices where sub could fully fit in main.
    for start in 0..=(n - m) {
        if check_match_at(main, sub, start) {
            return true;
        }
    }

    false
}